def visible_masts(heights):
    n = len(heights)
    seen = []
    for i in range(n):
        count, tallest = 0, 0
        for j in range(i + 1, n):
            if tallest < min(heights[i], heights[j]):
                count += 1
            tallest = max(tallest, heights[j])
            if tallest > heights[i]:
                break
        seen.append(count)
    return seen

def visible_masts(heights):
    n = len(heights)
    seen = [0] * n
    stack = []  # positions waiting for a taller mast
    nxt = [n] * n
    for i, h in enumerate(heights):
        while stack and heights[stack[-1]] < h:
            nxt[stack.pop()] = i
        stack.append(i)
    for i in range(n):
        seen[i] = nxt[i] - i if nxt[i] < n else n - 1 - i
    return seen
